import{_ as r,o,c as e,a2 as n}from"./chunks/framework.Dkj3JE0_.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/JLPT-N2/Quiz/misses.md","filePath":"blogs/JLPT-N2/Quiz/misses.md"}'),s={name:"blogs/JLPT-N2/Quiz/misses.md"};function a(g,t,i,p,h,l){return o(),e("div",null,[...t[0]||(t[0]=[n('<h2 id="_2026-10-13-—-quantifier-ください" tabindex="-1">2026-10-13 — Quantifier + ください <a class="header-anchor" href="#_2026-10-13-—-quantifier-ください" aria-label="Permalink to &quot;2026-10-13 — Quantifier + ください&quot;">​</a></h2><p><strong>Q:</strong> You want two flat tickets — 「Nを2枚ください」 or 「二枚でお願いします」?</p><p><strong>Covered:</strong> Natural order is <strong>Nを2枚ください</strong> (object + を + quantifier + ください). <strong>でお願いします</strong> is for means / chosen option once the item is clear.</p><p><strong>Gap:</strong> Used で where the counting pattern needs を.</p><h2 id="_2026-10-13-—-type-i-polite-negative" tabindex="-1">2026-10-13 — Type I polite negative <a class="header-anchor" href="#_2026-10-13-—-type-i-polite-negative" aria-label="Permalink to &quot;2026-10-13 — Type I polite negative&quot;">​</a></h2><p><strong>Q:</strong> Polite negative of 寒い — and with あまり?</p><p><strong>Covered:</strong> <strong>寒くありません</strong>; <strong>あまり寒くありません</strong>. Not <strong>寒くではありません</strong> (では is Type II / noun).</p><p><strong>Gap:</strong> Mixed Type I く-form with the では negative pattern.</p><h2 id="_2026-10-13-—-も-replaces-を" tabindex="-1">2026-10-13 — も replaces を <a class="header-anchor" href="#_2026-10-13-—-も-replaces-を" aria-label="Permalink to &quot;2026-10-13 — も replaces を&quot;">​</a></h2><p><strong>Q:</strong> Add “hot coffee too” after an order.</p><p><strong>Covered:</strong> <strong>ホットコーヒーもください</strong>. <strong>も</strong> replaces <strong>を</strong> — they do not stack.</p><p><strong>Gap:</strong> Kept を together with も.</p><h2 id="_2026-10-13-—-past-negative-全然" tabindex="-1">2026-10-13 — Past negative + 全然 <a class="header-anchor" href="#_2026-10-13-—-past-negative-全然" aria-label="Permalink to &quot;2026-10-13 — Past negative + 全然&quot;">​</a></h2><p><strong>Q:</strong> Past polite negative with 全然 for 難しい.</p><p><strong>Covered:</strong> <strong>全然難しくありませんでした</strong>. Slip: writing <strong>ではありませんでした</strong> on a Type I adjective.</p><p><strong>Gap:</strong> Past-negative spelling / pattern confusion with Type II–noun では.</p><h2 id="_2026-10-14-—-だれが-→-then-は" tabindex="-1">2026-10-14 — だれが → then は <a class="header-anchor" href="#_2026-10-14-—-だれが-→-then-は" aria-label="Permalink to &quot;2026-10-14 — だれが → then は&quot;">​</a></h2><p><strong>Q:</strong> After だれが留学生ですか, once the person is named, が or は?</p><p><strong>Correct:</strong> Keep が on the identifying answer; later reference uses <strong>は</strong> (known topic). Ex: ジョージさん<strong>は</strong>今、先生の研究室にいます。</p><p><strong>Gap:</strong> Answered with が on the known name.</p><h2 id="_2026-10-14-—-ほしい-third-person" tabindex="-1">2026-10-14 — ほしい third person <a class="header-anchor" href="#_2026-10-14-—-ほしい-third-person" aria-label="Permalink to &quot;2026-10-14 — ほしい third person&quot;">​</a></h2><p><strong>Q:</strong> Third-person “want” with ほしいです?</p><p><strong>Correct:</strong> ほしいです ≈ speaker only. Third person → <strong>ほしがっています</strong>.</p><p><strong>Gap:</strong> Used ほしいです for third person.</p><h2 id="_2026-10-14-—-ほど-ない" tabindex="-1">2026-10-14 — ほど～ない <a class="header-anchor" href="#_2026-10-14-—-ほど-ない" aria-label="Permalink to &quot;2026-10-14 — ほど～ない&quot;">​</a></h2><p><strong>Q:</strong> “Not as … as …” comparison frame?</p><p><strong>Correct:</strong> N₂ は N₁ ほど ～ない（e.g. 日本は中国ほど広くありません）.</p><p><strong>Gap:</strong> より / のほうが solid; ほど～ない missed.</p><h2 id="_2026-10-16-—-帰る-is-a-u-verb" tabindex="-1">2026-10-16 — 帰る is a u-verb <a class="header-anchor" href="#_2026-10-16-—-帰る-is-a-u-verb" aria-label="Permalink to &quot;2026-10-16 — 帰る is a u-verb&quot;">​</a></h2><p><strong>Q:</strong> Is 帰る a ru-verb? What is its ます形?</p><p><strong>Correct:</strong> 帰る looks like a ru-verb but is a <strong>u-verb (godan)</strong>: ます形 <strong>帰ります</strong>.</p><p><strong>Gap:</strong> Treated 帰る as ichidan.</p><h2 id="_2026-10-16-—-advice-ほうがいい" tabindex="-1">2026-10-16 — Advice: ほうがいい <a class="header-anchor" href="#_2026-10-16-—-advice-ほうがいい" aria-label="Permalink to &quot;2026-10-16 — Advice: ほうがいい&quot;">​</a></h2><p><strong>Q:</strong> How do you give advice with a verb vs a noun?</p><p><strong>Correct:</strong> <strong>Vたほうがいい</strong> (休んだほうがいい); for nouns <strong>Nのほうがいい</strong> (水のほうがいい). じゃありませんか is not advice.</p><p><strong>Gap:</strong> Mixed advice with じゃありませんか.</p><h2 id="_2026-10-17-—-nに-marks-the-recipient" tabindex="-1">2026-10-17 — Nに marks the recipient <a class="header-anchor" href="#_2026-10-17-—-nに-marks-the-recipient" aria-label="Permalink to &quot;2026-10-17 — Nに marks the recipient&quot;">​</a></h2><p><strong>Q:</strong> In 中村さんに資料をメールで送りました, who sent and who received?</p><p><strong>Correct:</strong> <strong>Nに</strong> = recipient: “I sent the documents <strong>to</strong> Nakamura-san.” The sender would take <strong>が</strong>.</p><p><strong>Gap:</strong> Read Nakamura as the sender.</p><h2 id="_2026-10-17-—-nなら-for-advice" tabindex="-1">2026-10-17 — Nなら for advice <a class="header-anchor" href="#_2026-10-17-—-nなら-for-advice" aria-label="Permalink to &quot;2026-10-17 — Nなら for advice&quot;">​</a></h2><p><strong>Q:</strong> Reply “If it’s a computer, this one is good.”</p><p><strong>Correct:</strong> <strong>パソコンなら、こちらがいいですよ</strong> / <strong>日本料理なら、駅前の店がいいですよ</strong>. なら picks up the listener’s topic; について just means “about”.</p><p><strong>Gap:</strong> Chose について instead of なら.</p><h2 id="_2026-10-17-—-ほしいなら-vs-ながら" tabindex="-1">2026-10-17 — ほしいなら vs ながら <a class="header-anchor" href="#_2026-10-17-—-ほしいなら-vs-ながら" aria-label="Permalink to &quot;2026-10-17 — ほしいなら vs ながら&quot;">​</a></h2><p><strong>Q:</strong> “If you want one, …”</p><p><strong>Correct:</strong> <strong>ほしいなら</strong>. ながら means “while” and attaches to a verb stem.</p><p><strong>Gap:</strong> Wrote ほしながら.</p><h2 id="_2026-10-17-—-聞く-ask-past-tense" tabindex="-1">2026-10-17 — 聞く: ask, past tense <a class="header-anchor" href="#_2026-10-17-—-聞く-ask-past-tense" aria-label="Permalink to &quot;2026-10-17 — 聞く: ask, past tense&quot;">​</a></h2><p><strong>Q:</strong> “I asked my friend about the plans.”</p><p><strong>Correct:</strong> <strong>友達に予定について聞きました</strong>. 聞く = ask (聴く = listen); past <strong>聞きました</strong>, te-form <strong>聞いて</strong>.</p><p><strong>Gap:</strong> Wrote 聴いでました.</p><h2 id="_2026-10-17-—-スケジュール-spelling" tabindex="-1">2026-10-17 — スケジュール spelling <a class="header-anchor" href="#_2026-10-17-—-スケジュール-spelling" aria-label="Permalink to &quot;2026-10-17 — スケジュール spelling&quot;">​</a></h2><p><strong>Q:</strong> Katakana for “schedule”?</p><p><strong>Correct:</strong> <strong>スケジュール</strong> (ケ, not ゲ).</p><p><strong>Gap:</strong> Wrote スゲジュール.</p><h2 id="_2026-10-17-—-も-after-で" tabindex="-1">2026-10-17 — も after で <a class="header-anchor" href="#_2026-10-17-—-も-after-で" aria-label="Permalink to &quot;2026-10-17 — も after で&quot;">​</a></h2><p><strong>Q:</strong> “I also eat with chopsticks.”</p><p><strong>Correct:</strong> <strong>お箸でも食べます</strong>. も replaces を/が but is added after で/に/と.</p><p><strong>Gap:</strong> Wrote もで.</p><h2 id="_2026-10-18-—-purpose-movement-verb" tabindex="-1">2026-10-18 — Purpose + movement verb <a class="header-anchor" href="#_2026-10-18-—-purpose-movement-verb" aria-label="Permalink to &quot;2026-10-18 — Purpose + movement verb&quot;">​</a></h2><p><strong>Q:</strong> “I went to the library to study Japanese.”</p><p><strong>Correct:</strong> <strong>日本語を勉強しに図書館へ行きました</strong>. Went = 行きました, came = 来ました.</p><p><strong>Gap:</strong> Used the wrong movement verb.</p><h2 id="_2026-10-18-—-い-adjective-noun" tabindex="-1">2026-10-18 — い-adjective + noun <a class="header-anchor" href="#_2026-10-18-—-い-adjective-noun" aria-label="Permalink to &quot;2026-10-18 — い-adjective + noun&quot;">​</a></h2><p><strong>Q:</strong> “a new dictionary”</p><p><strong>Correct:</strong> <strong>新しい辞書</strong>. The い-adjective goes straight onto the noun; 辞書 is everyday, 辞典 more formal.</p><p><strong>Gap:</strong> Wrote 新の辞典.</p><h2 id="_2026-10-18-—-う-verb-negative" tabindex="-1">2026-10-18 — う-verb negative <a class="header-anchor" href="#_2026-10-18-—-う-verb-negative" aria-label="Permalink to &quot;2026-10-18 — う-verb negative&quot;">​</a></h2><p><strong>Q:</strong> Past negative of 買う?</p><p><strong>Correct:</strong> <strong>買わなかった</strong> (う → わ before ない).</p><p><strong>Gap:</strong> Wrote 買いなかった.</p><h2 id="_2026-10-19-—-te-form-repeat-miss" tabindex="-1">2026-10-19 — Te-form (repeat miss) <a class="header-anchor" href="#_2026-10-19-—-te-form-repeat-miss" aria-label="Permalink to &quot;2026-10-19 — Te-form (repeat miss)&quot;">​</a></h2><p><strong>Q:</strong> Te-forms of 書く, 聞く, 来る.</p><p><strong>Correct:</strong> <strong>書いて, 聞いて, 来て</strong>. Only ぐ verbs take いで; ぬ/ぶ/む verbs take んで.</p><p><strong>Gap:</strong> Wrote 書いで, 聞いで, 来で (the same いで slip as 聴いで on 10-17).</p><h2 id="_2026-10-19-—-たい-past-negative" tabindex="-1">2026-10-19 — たい past negative <a class="header-anchor" href="#_2026-10-19-—-たい-past-negative" aria-label="Permalink to &quot;2026-10-19 — たい past negative&quot;">​</a></h2><p><strong>Q:</strong> “I didn&#39;t want to watch it.”</p><p><strong>Correct:</strong> <strong>見たくなかったです</strong>.</p><p><strong>Gap:</strong> Wrote 見たくないでした.</p><h2 id="_2026-10-19-—-question-word-が-in-か分かりません" tabindex="-1">2026-10-19 — Question word + が in か分かりません <a class="header-anchor" href="#_2026-10-19-—-question-word-が-in-か分かりません" aria-label="Permalink to &quot;2026-10-19 — Question word + が in か分かりません&quot;">​</a></h2><p><strong>Q:</strong> “I don&#39;t know which one is correct.”</p><p><strong>Correct:</strong> <strong>どれが正しいか分かりません</strong> (が after the question word; 正しい + か, with no の).</p><p><strong>Gap:</strong> Used は and the wrong form of 正しい.</p><h2 id="_2026-10-19-—-n-にする" tabindex="-1">2026-10-19 — N にする <a class="header-anchor" href="#_2026-10-19-—-n-にする" aria-label="Permalink to &quot;2026-10-19 — N にする&quot;">​</a></h2><p><strong>Q:</strong> “For my drink, I&#39;ll have tea.”</p><p><strong>Correct:</strong> <strong>飲み物はお茶にします</strong>.</p><p><strong>Gap:</strong> Wrote お茶を飲み物を選ぶ.</p><h2 id="_2026-10-19-—-な-before-ので" tabindex="-1">2026-10-19 — な before ので <a class="header-anchor" href="#_2026-10-19-—-な-before-ので" aria-label="Permalink to &quot;2026-10-19 — な before ので&quot;">​</a></h2><p><strong>Q:</strong> “This document is important, so …”</p><p><strong>Correct:</strong> <strong>この資料は大事なので</strong>.</p><p><strong>Gap:</strong> Left out the な.</p><h2 id="_2026-10-20-—-今-means-now" tabindex="-1">2026-10-20 — 今 means now <a class="header-anchor" href="#_2026-10-20-—-今-means-now" aria-label="Permalink to &quot;2026-10-20 — 今 means now&quot;">​</a></h2><p><strong>Q:</strong> Translate 今、雨が降っています。</p><p><strong>Correct:</strong> <strong>It&#39;s raining now.</strong> 今（いま）= now; today is 今日（きょう）.</p><p><strong>Gap:</strong> Translated it as “Today is raining”.</p><h2 id="_2026-10-20-—-会議中-reading" tabindex="-1">2026-10-20 — 会議中 reading <a class="header-anchor" href="#_2026-10-20-—-会議中-reading" aria-label="Permalink to &quot;2026-10-20 — 会議中 reading&quot;">​</a></h2><p><strong>Q:</strong> Read 会議中.</p><p><strong>Correct:</strong> <strong>かいぎちゅう</strong>. ～中（ちゅう）= in the middle of an activity (営業中, 準備中); ～中（じゅう）= throughout a span (一日中 いちにちじゅう, 世界中).</p><p><strong>Gap:</strong> Read it as かいぎじゅう.</p><h2 id="_2026-10-22-—-なきゃ-なくちゃ-short-forms" tabindex="-1">2026-10-22 — なきゃ／なくちゃ short forms <a class="header-anchor" href="#_2026-10-22-—-なきゃ-なくちゃ-short-forms" aria-label="Permalink to &quot;2026-10-22 — なきゃ／なくちゃ short forms&quot;">​</a></h2><p><strong>Q:</strong> Casual short forms of なければならない／なくてはならない.</p><p><strong>Correct:</strong> <strong>なければ → なきゃ</strong>, <strong>なくては → なくちゃ</strong> (行かなきゃ。／行かなくちゃ。). ちゃ comes from ては; じゃ comes from では.</p><p><strong>Gap:</strong> Answered なくじゃ.</p><h2 id="_2026-10-23-—-lesson-grammar-quiz-6-5-10" tabindex="-1">2026-10-23 — Lesson grammar quiz (6.5/10) <a class="header-anchor" href="#_2026-10-23-—-lesson-grammar-quiz-6-5-10" aria-label="Permalink to &quot;2026-10-23 — Lesson grammar quiz (6.5/10)&quot;">​</a></h2><p><strong>Q1:</strong> Indirect quotation of 「それはいいですね」と答えました.</p><p><strong>Correct:</strong> <strong>それはいいねと答えました</strong>. Plain form; ね stays. ですか → か is only for questions.</p><p><strong>Gap:</strong> Wrote それはいいか.</p><p><strong>Q2:</strong> &quot;I think George has his part-time job on Thursday too.&quot; (half credit)</p><p><strong>Correct:</strong> <strong>ジョージさんは木曜日にもアルバイトがあると思います。</strong> Plain form before と.</p><p><strong>Gap:</strong> Used the polite form (バイトします) before と思います.</p><p><strong>Q3:</strong> &quot;I&#39;ll take a bath after watching anime.&quot;</p><p><strong>Correct:</strong> <strong>アニメを見た後で、お風呂に入ります。</strong> The first action goes before 後で, in the た-form.</p><p><strong>Gap:</strong> Reversed the order (お風呂の後でアニメを見ます).</p><p><strong>Q4:</strong> &quot;This company has only two employees.&quot; (しか)</p><p><strong>Correct:</strong> <strong>この会社は社員が2人しかいません。</strong> しか + negative verb; だけ takes an affirmative verb (2人だけいます).</p><p><strong>Gap:</strong> Wrote 職員二人だけがいます.</p><h2 id="_2026-10-24-—-lesson-grammar-quiz-7-5-8" tabindex="-1">2026-10-24 — Lesson grammar quiz (7.5/8) <a class="header-anchor" href="#_2026-10-24-—-lesson-grammar-quiz-7-5-8" aria-label="Permalink to &quot;2026-10-24 — Lesson grammar quiz (7.5/8)&quot;">​</a></h2><p><strong>Q7:</strong> &quot;You can&#39;t buy this car for 2 million yen.&quot; (で for a quantity limit)</p><p><strong>Correct:</strong> <strong>この車は200万円では買えませんよ。</strong> Yen is 円; では is usual with a negative.</p><p><strong>Gap:</strong> Wrote 二百万園で買えません (園 for 円). Grammar point right.</p><p><strong>Q8:</strong> Pass on the manager&#39;s message: &quot;He said he&#39;ll be a little late, so we should start without him.&quot; (half credit)</p><p><strong>Correct:</strong> <strong>すこし遅れるから、先に始めてくださいと言っていました。</strong> The quote is a request (始めてください), not 始めましょう. &quot;A little&quot; is ちょっと／すこし.</p><p><strong>Gap:</strong> Wrote ちょと遅れるので、先に始めましょうと言っていました.</p><h2 id="_2026-10-25-—-lesson-grammar-quiz-8-5-10" tabindex="-1">2026-10-25 — Lesson grammar quiz (8.5/10) <a class="header-anchor" href="#_2026-10-25-—-lesson-grammar-quiz-8-5-10" aria-label="Permalink to &quot;2026-10-25 — Lesson grammar quiz (8.5/10)&quot;">​</a></h2><p><strong>N ではなく（て）:</strong> spoken form (half credit)</p><p><strong>Correct:</strong> <strong>文化じゃなくて</strong> (or ではなくて). The spoken forms keep the て; ではなく is the written form.</p><p><strong>Gap:</strong> Wrote 文化じゃなく.</p><p><strong>N である:</strong> past negative (half credit)</p><p><strong>Correct:</strong> <strong>首都ではなかった</strong>. In である style, the past negative is ではなかった.</p><p><strong>Gap:</strong> Wrote 首都ではありませんでした (polite です style).</p><p><strong>～すぎる:</strong> linking to a reason (half credit)</p><p><strong>Correct:</strong> <strong>この辺りはにぎやかすぎて、勉強にはよくない。</strong></p><p><strong>Gap:</strong> Wrote にぎやかすぎる; linking to the result needs すぎて.</p>',134)])])}const u=r(s,[["render",a]]);export{c as __pageData,u as default};
